head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.secugrpId = 'PF';
scwin.secugrpNm = '상장형수익증권';
scwin.vSearchDate = "";
scwin.pJobTitl = $c.session.getUserInfo("jobtitl");
// var listBzTpCd = LIST_BZ_TP_CD_813; // PF 매매거래정지
scwin.loading1, scwin.loading2, scwin.loading3, scwin.loading4, scwin.loading5, scwin.loading6;
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const vCurDate = $c.date.getServerDateTime("yyyyMMdd");
        edt_ConfirmDate.setValue(vCurDate);
        await scwin.listSync();
        txb_cnt1.setValue(dlt_firstDetect.getRowCount());
        txb_cnt2.setValue(dlt_noti.getRowCount());
        txb_cnt3.setValue(dlt_extn.getRowCount());
        txb_cnt4.setValue(dlt_design.getRowCount());
        txb_cnt5.setValue(dlt_release.getRowCount());
        txb_cnt6.setValue(dlt_trdhalt.getRowCount());
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09350.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
