///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listDtl
 * @description list Dtl 처리
 * @param {*} type type
 * @param {*} nowOld nowOld
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listDtl = async function(type, nowOld) {
    //let urlcond = '';
    //urlcond += "&BAS_DD=" + edt_ConfirmDate.getValue();
    //urlcond += "&SECUGRP_ID=" + scwin.secugrpId;
    let datasetId = "";
    let url_list = "";
    if (nowOld === "OLD") {
        if (type === "01") {
            // 최초적출
            //urlcond += "&ETP_INVSTWARN_CD=" + "01";
            url_list = "/api/listing/lstproc/pf/invst-warn/select-list-first-detect";
            datasetId = "dlt_firstDetect";
        } else if (type === "02") {
            // 지정예고
            //urlcond += "&ETP_INVSTWARN_CD=" + "02";
            url_list = "/api/listing/lstproc/pf/invst-warn/select-list-noti";
            datasetId = "dlt_noti";
        } else if (type === "04") {
            // 지정연장
            //urlcond += "&ETP_INVSTWARN_CD=" + "04";
            url_list = "/api/listing/lstproc/pf/invst-warn/select-list-extn";
            datasetId = "dlt_extn";
        } else if (type === "03") {
            // 지정
            //urlcond += "&ETP_INVSTWARN_CD=" + "03";
            url_list = "/api/listing/lstproc/pf/invst-warn/select-list-design";
            datasetId = "dlt_design";
        } else if (type === "05") {
            // 지정해제
            //urlcond += "&ETP_INVSTWARN_CD=" + "05";
            url_list = "/api/listing/lstproc/pf/invst-warn/select-list-release";
            datasetId = "dlt_release";
        } else if (type === "06") {
            // 매매거래정지, 매매거래정지 해제, 매매거래정지 및 해제
            //urlcond += "&ETP_INVSTWARN_CD=" + "06";
            url_list = "/api/listing/lstproc/pf/invst-warn/select-list-trd-halt";
            datasetId = "dlt_trdhalt";
        }
    } else {
        if (type === "01") {
            // 최초적출
            url_list = "/api/listing/lstproc/pf/invst-warn/select-list-first-detect";
            datasetId = "dlt_firstDetect";
        } else if (type === "02") {
            // 지정예고
            url_list = "/api/listing/lstproc/pf/invst-warn/select-list-noti";
            datasetId = "dlt_noti";
        } else if (type === "04") {
            // 지정연장
            url_list = "/api/listing/lstproc/pf/invst-warn/select-list-extn";
            datasetId = "dlt_extn";
        } else if (type === "03") {
            // 지정
            url_list = "/api/listing/lstproc/pf/invst-warn/select-list-design";
            datasetId = "dlt_design";
        } else if (type === "05") {
            // 지정해제
            url_list = "/api/listing/lstproc/pf/invst-warn/select-list-release";
            datasetId = "dlt_release";
        } else if (type === "06") {
            // 매매거래정지, 매매거래정지 해제, 매매거래정지 및 해제
            //urlcond += "&LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_813;
            url_list = "/api/listing/lstproc/pf/invst-warn/select-list-trd-halt";
            datasetId = "dlt_trdhalt";
        }
    }
    //url_list += urlcond;
    //url_list += "&SCREN_ID=" + "ULDSTF09350.xml";
    //url_list += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_datasetId",
        action : url_list,
        method: "get",
        ref : "dma_searchReq",
        target : datasetId + "=body",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name trsRevw
 * @description 담당자 확인
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trsRevw = async function() {
    //await scwin.trSetHeader();
    //dts_Cls.setCellData(1, "EMP_NO", js_emp_no);
    //dts_Cls.setCellData(1, "SECUGRP_ID", scwin.secugrpId);

    dma_reviewReq.set("completeYn", true);
    dma_reviewReq.set("completeCtnt", "확인완료");
    //trs_revw.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_revw",
        action : "/api/listing/lstproc/pf/invst-warn/review",
        method: "post",
        ref : "dma_reviewReq",
        //target : "trs_revw=body",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    scwin.trs_revw_OnSuccess();
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name trsAprv
 * @description 팀장승인
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trsAprv = async function() {
    //await scwin.trSetHeader();
    //dts_Cls.setCellData(1, "EMP_NO", js_emp_no);
    //dts_Cls.setCellData(1, "SECUGRP_ID", scwin.secugrpId);
    //trs_aprv.KeyName = "toinb_dataid4";

    const aprvList = new Array();

    var cnt = 0;
    for(var i=0; i<dlt_firstDetect.getTotalRow(); i++) {
        aprvList[cnt] = dlt_firstDetect.getRowJSON(i);
        cnt++;
    }
    for(var i=0; i<dlt_noti.getTotalRow(); i++) {
        aprvList[cnt] = dlt_noti.getRowJSON(i);
        cnt++;
    }
    for(var i=0; i<dlt_extn.getTotalRow(); i++) {
        aprvList[cnt] = dlt_extn.getRowJSON(i);
        cnt++;
    }
    for(var i=0; i<dlt_design.getTotalRow(); i++) {
        aprvList[cnt] = dlt_design.getRowJSON(i);
        cnt++;
    }
    for(var i=0; i<dlt_release.getTotalRow(); i++) {
        aprvList[cnt] = dlt_release.getRowJSON(i);
        cnt++;
    }
    for(var i=0; i<dlt_trdhalt.getTotalRow(); i++) {
        aprvList[cnt] = dlt_trdhalt.getRowJSON(i);
        cnt++;
    }

    dma_approveReq.set("pfInvstWarnClosingHistList", aprvList);
    const sbmOptions = {
        id : "sbm_aprv",
        action : "/api/listing/lstproc/pf/invst-warn/approve",
        method: "post",
        ref : "dma_approveReq",
        //target : "trs_aprv=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    scwin.trs_aprv_OnSuccess();
};

/**
 * @method
 * @name trSetHeader
 * @description tr Set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
// scwin.trSetHeader = async function() {
//     const sbmOptions = {
//         id : "sbm_dts_Cls",
//         action : "/gauceSystemierAdaptor.do",
//         ref : "",
//         target : "dts_Cls=body.content",
