/**
 * @method
 * @name dateErrCheck
 * @description date Err Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateErrCheck = async function() {
    if (edt_ConfirmDate.getValue() === "" || edt_ConfirmDate.getValue().length < 8) {
        await $c.win.alert("마감일을 입력하세요.");
        edt_ConfirmDate.focus();
        return true;
    }
};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (await scwin.dateErrCheck()) {
        return;
    }
    scwin.loading1 = false;
    scwin.loading2 = false;
    scwin.loading3 = false;
    scwin.loading4 = false;
    scwin.loading5 = false;
    scwin.loading6 = false;
    let nowOld = "NOW";
    let curDd = $c.date.getServerDateTime("yyyyMMdd");
    let searchDate = edt_ConfirmDate.getValue();
    // 마감일이 오늘이 아니면 이력조회
    if (curDd !== searchDate) {
        nowOld = "OLD";
    }
    await scwin.clslogSync();
    // 팀장 마감이 되었다면 이력조회
    const apprvEmpNm = txb_APPROVR_EMP_NM.getValue();
    if (apprvEmpNm.length > 0) {
        nowOld = "OLD";
    }
    scwin.vSearchDate = edt_ConfirmDate.getValue();
    await scwin.getJungBoBatch();
    await scwin.listDtl("01", nowOld);
    scwin.dlt_firstDetect_OnLoadCompleted();
    await scwin.listDtl("02", nowOld);
    scwin.dlt_noti_OnLoadCompleted();
    await scwin.listDtl("03", nowOld);
    scwin.dlt_extn_OnLoadCompleted();
    await scwin.listDtl("04", nowOld);
    scwin.dlt_design_OnLoadCompleted();
    await scwin.listDtl("05", nowOld);
    scwin.dlt_release_OnLoadCompleted();
    await scwin.listDtl("06", nowOld);
    scwin.dlt_trdhalt_OnLoadCompleted();
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    const today = $c.date.getServerDateTime("yyyyMMddHHmmss");
    // 파일형식 today_화면명.xls
    //const xls_path = $c.session.getExcelDownPath() + today + scwin.secugrpNm + "투자유의종목마감.xls";
    //$c.data.saveExcel(grd_List1, "최초적출", false, false, false, xls_path);
    if(dlt_firstDetect.getRowCount() > 0) {
        $c.data.downloadGridViewExcel(grd_List1, {fileName: "투자유의종목_최초적출"+today, sheetName: "최초적출", type: 40});
    }
    if (dlt_noti.getRowCount() > 0) {
        $c.data.downloadGridViewExcel(grd_List2, {fileName: "투자유의종목_지정예고"+today, sheetName: "지정예고", type: 40});
    }
    if (dlt_extn.getRowCount() > 0) {
        $c.data.downloadGridViewExcel(grd_List3, {fileName: "투자유의종목_지정연장"+today, sheetName: "지정연장", type: 40});
    }
    if (dlt_design.getRowCount() > 0) {
        $c.data.downloadGridViewExcel(grd_List4, {fileName: "투자유의종목_지정"+today, sheetName: "지정", type: 40});
    }
    if (dlt_release.getRowCount() > 0) {
        $c.data.downloadGridViewExcel(grd_List5, {fileName: "투자유의종목_지정해제"+today, sheetName: "지정해제", type: 40});
    }
    if (dlt_trdhalt.getRowCount() > 0) {
        $c.data.downloadGridViewExcel(grd_List6, {fileName: "투자유의종목_매매거래정지"+today, sheetName: "매매거래정지", type: 40});
    }
};

/**
 * @method
 * @name chkIsClose
 * @description 마감가능여부 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkIsClose = async function() {
    let isCheck = true;
    let curDd = $c.date.getServerDateTime("yyyyMMdd");
    let searchDate = edt_ConfirmDate.getValue();
    if (curDd !== searchDate || scwin.vSearchDate !== curDd) {
        await $c.win.alert("당일날짜만 마감가능합니다. 마감일을 확인하세요");
        isCheck = false;
    }
    return isCheck;
};

/**
 * @method
 * @name revw
 * @description 담당자 확인 버튼 클릭시
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.revw = async function() {
    procJob = "담당자 확인";
    if (await scwin.chkIsClose()) {
        let res = await $c.win.confirm(procJob + " 마감처리 하시겠습니까?");
        if (res) {
            await scwin.trsRevw();
        }
    }
};

/**
 * @method
 * @name aprv
 * @description 팀장승인 버튼 클릭시
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.aprv = async function() {
    if (scwin.loading1 && scwin.loading2 && scwin.loading3 && scwin.loading4 && scwin.loading5 && scwin.loading6) {
        if (await scwin.chkIsClose()) {
            procJob = "팀장승인";
            if (txb_CONFRM_DDTM.getValue() === "") {
                await $c.win.alert("담당자확인 완료 후 승인처리 가능합니다.");
                return false;
            } else {
                let res = await $c.win.confirm(procJob + " 마감처리 하시겠습니까?");
                if (res) {
                    await scwin.trsAprv();
                }
            }
        }
    } else {
        await $c.win.alert("데이터가 로딩중입니다. 로딩후에 승인가능합니다.");
    }
};

