/**
 * @method
 * @name checkDupList
 * @description 각 단계별 중복종목 리스트 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkDupList = async function() {
    if (!scwin.loopDataSet(dlt_firstDetect)) {
        await $c.win.alert("투자유의종목 최초적출 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
    }
    if (!scwin.loopDataSet(dlt_noti)) {
        await $c.win.alert("투자유의종목 지정예고 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
    }
    if (!scwin.loopDataSet(dlt_extn)) {
        await $c.win.alert("투자유의종목 지정연장 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
    }
    if (!scwin.loopDataSet(dlt_design)) {
        await $c.win.alert("투자유의종목 지정 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
    }
    if (!scwin.loopDataSet(dlt_release)) {
        await $c.win.alert("투자유의종목 지정해제 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
    }
    if (!scwin.loopDataSet(dlt_trdhalt)) {
        await $c.win.alert("투자유의종목 매매거래정지 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
    }
};

/**
 * @method
 * @name loopDataSet
 * @description loop Data Set 처리
 * @param {String} dtsId dtsId
 * @returns {void}
 * @hidden N
 */
scwin.loopDataSet = function(dtsId) {
    let tempData = "";
    let checkData = "";
    for (let i = 1, j = dtsId.getRowCount(); i <= j; i++) {
        tempData = dtsId.getCellData(i, "ISU_CD");
        for (let k = 1, l = dtsId.getRowCount(); k <= l; k++) {
            if (i === k) {
                continue;
            }
            checkData = dtsId.getCellData(k, "ISU_CD");
            if (tempData === checkData) {
                return false;
            }
        }
    }
    return true;
};
